# Check test input for connected components
def find_component_8way(r, c, grid):
    """Find component using 8-way connections"""
    visited = set()
    stack = [(r, c)]
    comp = []

    while stack:
        rr, cc = stack.pop()
        if (rr, cc) in visited:
            continue
        visited.add((rr, cc))
        comp.append((rr, cc))

        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = rr + dr, cc + dc
                if 0 <= nr < 15 and 0 <= nc < 15:
                    if grid[nr][nc] != 0 and (nr, nc) not in visited:
                        stack.append((nr, nc))
    return comp

